source='''def transform(grid):
    n, m = len(grid), len(grid[0])
    best_h, best_score = 0, -1.0
    for h in range(2 * n - 1):
        same = total = 0
        for r in range(n):
            rr = h - r
            if 0 <= rr < n and rr != r:
                for a, b in zip(grid[r], grid[rr]):
                    if a != 6 and b != 6:
                        total += 1
                        same += a == b
        score = same / total if total else 0
        if score > best_score:
            best_h, best_score = h, score
    def orbit(r, c):
        seen = {(r, c)}
        todo = [(r, c)]
        while todo:
            a, b = todo.pop()
            for x, y in ((b, a), (best_h - a, b), (a, best_h - b)):
                if 0 <= x < n and 0 <= y < m and (x, y) not in seen:
                    seen.add((x, y))
                    todo.append((x, y))
        return seen
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                values = [grid[a][b] for a, b in orbit(r, c) if grid[a][b] != 6]
                if values:
                    out[r][c] = values[0]
                else:
                    out[r][c] = 2
    return out
